using System.Collections.Generic;

namespace TAOM.Features.TroopProgression;

// Volunteer recruitment pool for Angaladh, the Woodmen of Mirkwood (troops generated by
// tools/generate_angaladh_troops.py). The data half of VolunteerRecruitmentService, registered by
// the static ctor in the core file. Lookup priority: conditional > settlement > clan > culture
// (troops.md).
public partial class VolunteerRecruitmentService
{
    private static void InitializeAngaladhCulture()
    {
        // Two roots reach the whole tree: the Levy heads the spear, axe and bow lines, and the
        // Ironwood Youth heads the Ironwood guard to the Woodmen Guard. Levy-heavy, as Cardolan's.
        CultureMap["angaladh"] = new List<VolunteerChance>
        {
            new VolunteerChance("angaladh_levy", 6),
            new VolunteerChance("angaladh_ironwood_youth", 2)
        };
    }
}
